{"files":[{"path":"lib/lore/compile-query.ts","content":"/**
 * NL -> FilterSpec compiler: the ONLY probabilistic step in the retrieval
 * plane. One structured-output call maps free text onto the versioned filter
 * schema, grounded in the live field catalog + value vocabulary (schema
 * linking). Execution of the result is fully deterministic and replayable;
 * users edit the result as chips without re-invoking the LLM.
 */
import { generateObject } from "ai";
import { z } from "zod";
import type { FilterPredicate, FilterSpec } from "@lore/core";
import { esAdapter } from "./adapters";
import { buildChips } from "./chips";
import { PROFILE_FIELDS } from "./fields";
import { CELL_DECODE, DEFAULT_MODEL } from "./models";

const KEYWORD_FIELDS = PROFILE_FIELDS.filter((f) => f.type === "keyword").map(
  (f) => f.name,
);
const NUMERIC_FIELDS = PROFILE_FIELDS.filter((f) => f.type === "float").map(
  (f) => f.name,
);

const keywordField = z.enum(KEYWORD_FIELDS as [string, ...string[]]);
const numericField = z.enum(NUMERIC_FIELDS as [string, ...string[]]);

const TermSchema = z.object({
  kind: z.literal("term"),
  field: keywordField,
  value: z.string(),
});
const TermsSchema = z.object({
  kind: z.literal("terms"),
  field: keywordField,
  values: z.array(z.string()).min(1),
});
const RangeSchema = z.object({
  kind: z.literal("range"),
  field: numericField,
  min: z.number().optional(),
  max: z.number().optional(),
});
const ExistsSchema = z.object({
  kind: z.literal("exists"),
  field: z.enum([...KEYWORD_FIELDS, ...NUMERIC_FIELDS] as [string, ...string[]]),
});
const InnerPredicate = z.discriminatedUnion("kind", [
  TermSchema,
  TermsSchema,
  RangeSchema,
  ExistsSchema,
]);
const NotSchema = z.object({
  kind: z.literal("not"),
  predicate: InnerPredicate,
});
const PredicateSchema = z.discriminatedUnion("kind", [
  TermSchema,
  TermsSchema,
  RangeSchema,
  ExistsSchema,
  NotSchema,
]);

const CompileOutput = z.object({
  all: z
    .array(PredicateSchema)
    .describe("Predicates that must ALL hold (AND semantics)"),
  any: z
    .array(PredicateSchema)
    .describe("Optional OR group: at least one must hold; empty if unused"),
  unmapped: z
    .array(z.string())
    .describe(
      "Parts of the query that could not be mapped to any field; empty if none",
    ),
});

export interface CompiledQuery {
  filter: FilterSpec;
  unmapped: string[];
  usage: { inputTokens: number; outputTokens: number };
}

// ---------------------------------------------------------------------------
// Vocabulary: top values per keyword field, computed live and cached.
// ---------------------------------------------------------------------------

let vocabCache: { at: number; text: string } | null = null;
const VOCAB_TTL_MS = 60 * 60 * 1000;

async function vocabulary(): Promise<string> {
  if (vocabCache && Date.now() - vocabCache.at < VOCAB_TTL_MS) {
    return vocabCache.text;
  }
  const agg = await esAdapter().aggregate(
    { schemaVersion: 1, all: [] },
    KEYWORD_FIELDS,
  );
  const lines = PROFILE_FIELDS.map((f) => {
    const base = `- ${f.name} (${f.type}${f.multiValued ? ", multi-valued" : ""}): ${f.description ?? ""}`;
    const buckets = agg[f.name];
    if (!buckets || buckets.length === 0) return base;
    const vals = buckets
      .slice(0, 40)
      .map((b) => JSON.stringify(b.value))
      .join(", ");
    return `${base}\n  values: ${vals}`;
  });
  vocabCache = { at: Date.now(), text: lines.join("\n") };
  return vocabCache.text;
}

// ---------------------------------------------------------------------------
// Compile
// ---------------------------------------------------------------------------

const SYSTEM = `You compile a recruiter-style natural-language query over a table of
89,184 developer profiles (Stack Overflow Survey 2023) into structured filter
predicates. Use ONLY the fields and, for keyword fields, ONLY values from the
vocabulary below (values are exact, case-sensitive strings). Rules:
- "senior"/"experienced" means years_code_pro >= 5 unless a number is given;
  "junior" means years_code_pro <= 2.
- Salary/compensation amounts map to converted_comp_yearly (USD).
- Students: main_branch "I am learning to code" OR employment containing
  "Student, full-time" / "Student, part-time" (use the any group).
- Negations ("not", "without", "excluding") compile to kind:"not".
- Multiple alternatives of the same facet ("Germany or France") compile to one
  kind:"terms" predicate, not an any-group.
- Use the any group ONLY for genuine cross-field OR requirements.
- Anything unmappable to these fields goes into unmapped, verbatim; never
  invent fields or values. Prefer precision over recall.

OUTPUT SHAPE — return a JSON object with EXACTLY these top-level keys:
"all" (array of predicates, AND), "any" (array of predicates, OR group, [] if
unused), "unmapped" (array of strings, [] if none). Predicate shapes, exactly:
  {"kind":"term","field":<field>,"value":<string>}
  {"kind":"terms","field":<field>,"values":[<string>,...]}
  {"kind":"range","field":<numeric field>,"min":<number>,"max":<number>} (min and/or max)
  {"kind":"exists","field":<field>}
  {"kind":"not","predicate":<one of the above>}
No other keys. Ranges use "min"/"max", never gt/gte/lt/lte.

<example>
Query: "remote TypeScript devs in Canada, not managers, 4+ years pro, or anyone at a 10k+ company"
{"all":[{"kind":"term","field":"remote_work","value":"Remote"},{"kind":"term","field":"languages","value":"TypeScript"},{"kind":"term","field":"country","value":"Canada"},{"kind":"not","predicate":{"kind":"term","field":"ic_or_pm","value":"People manager"}},{"kind":"range","field":"years_code_pro","min":4}],"any":[{"kind":"term","field":"org_size","value":"10,000 or more employees"}],"unmapped":[]}
</example>`;

export async function translateQuery(query: string): Promise<CompiledQuery> {
  const vocab = await vocabulary();
  const res = await generateObject({
    model: DEFAULT_MODEL,
    schema: CompileOutput,
    // Pinned like CELL_DECODE: at default sampling temperature this model
    // self-disagrees on 9.5% of draws vs 5.0% at T=0 (measured in the
    // paper), and an unpinned compile occasionally emits degenerate specs
    // (e.g. "NOT 38 languages" instead of "languages = Rust").
    ...CELL_DECODE,
    system: `${SYSTEM}\n\nFIELD CATALOG AND VOCABULARY:\n${vocab}`,
    prompt: `Query: ${JSON.stringify(query)}`,
  });
  const { all, any, unmapped } = res.object;
  const filter: FilterSpec = {
    schemaVersion: 1,
    all: all as FilterPredicate[],
    ...(any.length > 0 ? { any: any as FilterPredicate[] } : {}),
    chips: buildChips(all as FilterPredicate[], any as FilterPredicate[]),
  };
  return {
    filter,
    unmapped,
    usage: {
      inputTokens: res.usage.inputTokens ?? 0,
      outputTokens: res.usage.outputTokens ?? 0,
    },
  };
}

// Chip building lives in ./chips (pure, shared with the client UI).
"}],"concerns":[],"rationale":"Renamed the exported function compileQuery to translateQuery in lib/lore/compile-query.ts without altering any other code."}

{"files":[{"path":"lib/lore/adapters.ts","content":"import { ElasticsearchAdapter } from "@lore/adapter-elasticsearch";
import { MysqlAdapter } from "@lore/adapter-mysql";
import type { DataSourceAdapter } from "@lore/core";
import {
  PROFILE_ES_INDEX,
  PROFILE_FIELDS,
  PROFILE_ID_FIELD,
  PROFILE_TABLE,
} from "./fields";

/**
 * Server-side adapter registry. Both backends stay live so the demo can
 * switch between them per request and prove parity; `hybrid` searches ES and
 * hydrates rows from MySQL (source-of-truth pattern).
 */
export type BackendId = "elasticsearch" | "mysql" | "hybrid";

type Row = Record<string, unknown>;

const globals = globalThis as unknown as {
  __loreEs?: ElasticsearchAdapter<Row>;
  __loreMy?: MysqlAdapter<Row>;
};

export function esAdapter(): ElasticsearchAdapter<Row> {
  globals.__loreEs ??= new ElasticsearchAdapter<Row>({
    node: process.env.LORE_ES_URL ?? "http://localhost:9200",
    index: PROFILE_ES_INDEX,
    fields: PROFILE_FIELDS,
    idField: PROFILE_ID_FIELD,
  });
  return globals.__loreEs;
}

export function mysqlAdapter(): MysqlAdapter<Row> {
  globals.__loreMy ??= new MysqlAdapter<Row>({
    uri: process.env.LORE_MYSQL_URL ?? "mysql://root@localhost:3306/lore",
    table: PROFILE_TABLE,
    fields: PROFILE_FIELDS,
    idField: PROFILE_ID_FIELD,
  });
  return globals.__loreMy;
}

/** Hybrid: ES answers search/counts/facets; MySQL hydrates full rows by id. */
class HybridAdapter implements DataSourceAdapter<Row> {
  readonly id = "hybrid:es-search+mysql-hydrate";
  get capabilities() {
    return esAdapter().capabilities;
  }
  fields() {
    return esAdapter().fields();
  }
  count(filter: Parameters<DataSourceAdapter<Row>["count"]>[0]) {
    return esAdapter().count(filter);
  }
  async search(
    ...args: Parameters<DataSourceAdapter<Row>["search"]>
  ): ReturnType<DataSourceAdapter<Row>["search"]> {
    const page = await esAdapter().search(...args);
    const ids = page.rows.map((r) => String(r[PROFILE_ID_FIELD]));
    const hydrated = await mysqlAdapter().hydrate(ids);
    const byId = new Map(hydrated.map((r) => [String(r[PROFILE_ID_FIELD]), r]));
    return {
      ...page,
      rows: page.rows.map((r) => byId.get(String(r[PROFILE_ID_FIELD])) ?? r),
    };
  }
  aggregate(...args: Parameters<DataSourceAdapter<Row>["aggregate"]>) {
    return esAdapter().aggregate(...args);
  }
  hydrate(ids: string[]) {
    return mysqlAdapter().hydrate(ids);
  }
}

const hybrid = new HybridAdapter();

export function adapterForCore(backend: BackendId): DataSourceAdapter<Row> {
  if (backend === "mysql") return mysqlAdapter();
  if (backend === "hybrid") return hybrid;
  return esAdapter();
}
"}],"concerns":["Per the assignment I only edited lib/lore/adapters.ts; the call sites in app/api/lore/columns/[id]/certify/route.ts and app/api/lore/columns/[id]/run/route.ts still import and call adapterFor, so they must also be renamed to adapterForCore for the repository to build cleanly.","No currently listed worker appears assigned to update those two route files."],"rationale":"I renamed the exported adapterFor definition to adapterForCore in lib/lore/adapters.ts only, leaving all other files untouched as instructed."}

{"files":[{"path":"lib/password-auth.ts","content":"import { createHash, createHmac, timingSafeEqual } from "node:crypto";

export const PASSWORD_SESSION_COOKIE_NAME = "eve_chat_session";
export const PASSWORD_SESSION_MAX_AGE = 60 * 60 * 24 * 30;

const TOKEN_VERSION = "v1";

export function getChatPassword() {
  return process.env.EVE_CHAT_PASSWORD?.trim() ?? "";
}

export function verifyChatPassword(candidate: string) {
  const expected = getChatPassword();

  if (!expected) {
    return false;
  }

  return timingSafeEqual(hash(candidate), hash(expected));
}

export function makePasswordSessionToken(now = Date.now()) {
  const expiresAt = Math.floor(now / 1000) + PASSWORD_SESSION_MAX_AGE;
  const payload = `${TOKEN_VERSION}.${expiresAt}`;
  const signature = sign(payload);

  return `${payload}.${signature}`;
}

export function verifyPasswordSessionToken(token: string | undefined, now = Date.now()) {
  if (!token) {
    return false;
  }

  const [version, expiresAtRaw, signature, ...extra] = token.split(".");
  const expiresAt = Number(expiresAtRaw);

  if (
    version !== TOKEN_VERSION ||
    !signature ||
    extra.length > 0 ||
    !Number.isSafeInteger(expiresAt) ||
    expiresAt <= Math.floor(now / 1000)
  ) {
    return false;
  }

  const expected = sign(`${version}.${expiresAt}`);

  return timingSafeEqual(hash(signature), hash(expected));
}

export function getPasswordSessionFromHeaders(headers: Headers) {
  const cookieHeader = headers.get("cookie");

  if (!cookieHeader) {
    return false;
  }

  const token = cookieHeader
    .split(";")
    .map((cookie) => cookie.trim().split("="))
    .find(([name]) => name === PASSWORD_SESSION_COOKIE_NAME)?.[1];

  return verifyPasswordSessionToken(token ? decodeURIComponent(token) : undefined);
}

export function hasSameOriginRequest(request: Request) {
  const origin = request.headers.get("origin");
  const publicHost =
    request.headers.get("x-forwarded-host") ??
    request.headers.get("host");

  if (!origin || !publicHost) {
    return false;
  }

  try {
    const originUrl = new URL(origin);
    const forwardedProtocol = request.headers.get("x-forwarded-proto");

    return (
      originUrl.host === publicHost &&
      (!forwardedProtocol || originUrl.protocol === `${forwardedProtocol}:`)
    );
  } catch {
    return false;
  }
}

function hash(value: string) {
  return createHash("sha256").update(value).digest();
}

function sign(payload: string) {
  return createHmac("sha256", getChatPassword()).update(payload).digest("base64url");
}
"}],"concerns":[],"rationale":"Renamed the exported function in lib/password-auth.ts from createPasswordSessionToken to makePasswordSessionToken as assigned."}

{"files":[{"path":"lib/rate-limit.ts","content":"import { Redis } from "@upstash/redis";

type LimitOptions = {
  readonly key: string;
  readonly limit: number;
  readonly prefix: string;
  readonly windowSeconds: number;
};

export class RateLimitError extends Error {
  readonly retryAfter: number;

  constructor(retryAfter: number) {
    super("Too many requests. Please wait a moment and try again.");
    this.retryAfter = retryAfter;
  }
}

let redis: Redis | null | undefined;

function getRedisEnv() {
  const url = process.env.UPSTASH_REDIS_REST_URL?.trim() || process.env.KV_REST_API_URL?.trim();
  const token =
    process.env.UPSTASH_REDIS_REST_TOKEN?.trim() || process.env.KV_REST_API_TOKEN?.trim();

  return url && token ? { token, url } : null;
}

function getRedis() {
  if (redis !== undefined) {
    return redis;
  }

  const env = getRedisEnv();

  if (!env) {
    redis = null;
    return redis;
  }

  redis = new Redis(env);
  return redis;
}

export async function imposeRateLimit(options: LimitOptions) {
  const client = getRedis();

  if (!client) {
    return;
  }

  const now = Math.floor(Date.now() / 1000);
  const windowId = Math.floor(now / options.windowSeconds);
  const redisKey = `rate:${options.prefix}:${options.key}:${windowId}`;
  const count = await client.incr(redisKey);

  if (count === 1) {
    await client.expire(redisKey, options.windowSeconds);
  }

  if (count > options.limit) {
    const retryAfter = options.windowSeconds - (now % options.windowSeconds);
    throw new RateLimitError(retryAfter);
  }
}
"}],"concerns":[],"rationale":"Renamed the exported function enforceRateLimit to imposeRateLimit in lib/rate-limit.ts without making any other changes."}

{"files":[{"path":"lib/chat/provisional-chat.ts","content":"const PENDING_CHAT_STORAGE_MAX_AGE_MS = 10 * 60 * 1000;
const PENDING_CHAT_STORAGE_PREFIX = "eve-chat-pending:";
const PROVISIONAL_CHAT_ID_PREFIX = "new-";

type StoredPendingChat = {
  readonly createdAt: number;
  readonly pendingUserMessage: string;
  readonly version: 1;
};

export function makeProvisionalChatId() {
  const randomId =
    globalThis.crypto?.randomUUID?.() ??
    `${Date.now()}-${Math.random().toString(36).slice(2)}`;

  return `${PROVISIONAL_CHAT_ID_PREFIX}${randomId}`;
}

export function isProvisionalChatId(chatId: string) {
  return chatId.startsWith(PROVISIONAL_CHAT_ID_PREFIX);
}

export function writePendingChatMessage(chatId: string, message: string) {
  const pendingUserMessage = message.trim();

  if (!pendingUserMessage || typeof window === "undefined") {
    return false;
  }

  try {
    window.sessionStorage.setItem(
      getPendingChatStorageKey(chatId),
      JSON.stringify({
        createdAt: Date.now(),
        pendingUserMessage,
        version: 1,
      } satisfies StoredPendingChat),
    );
    return true;
  } catch {
    return false;
  }
}

export function readPendingChatMessage(chatId: string) {
  if (typeof window === "undefined") {
    return null;
  }

  const key = getPendingChatStorageKey(chatId);
  const stored = window.sessionStorage.getItem(key);

  if (!stored) {
    return null;
  }

  try {
    const parsed = JSON.parse(stored) as Partial<StoredPendingChat>;
    const createdAt = Number(parsed.createdAt);
    const pendingUserMessage = parsed.pendingUserMessage?.trim();

    if (
      !pendingUserMessage ||
      !Number.isFinite(createdAt) ||
      Date.now() - createdAt > PENDING_CHAT_STORAGE_MAX_AGE_MS
    ) {
      window.sessionStorage.removeItem(key);
      return null;
    }

    return pendingUserMessage;
  } catch {
    window.sessionStorage.removeItem(key);
    return null;
  }
}

export function clearPendingChatMessage(chatId: string) {
  if (typeof window === "undefined") {
    return;
  }

  window.sessionStorage.removeItem(getPendingChatStorageKey(chatId));
}

function getPendingChatStorageKey(chatId: string) {
  return `${PENDING_CHAT_STORAGE_PREFIX}${chatId}`;
}
